use std::process::Command;

fn run(b: &[u8]) -> String {
    use std::os::unix::ffi::OsStrExt;
    let arg = std::ffi::OsStr::from_bytes(b);
    let o = Command::new("/workspace/dataset/test4_executable").arg(arg).output().unwrap();
    String::from_utf8_lossy(&o.stdout).replace('\n', "")
}

fn model(b: &[u8]) -> String {
    let n = b.len();
    let l1 = if n >= 1 && n <= 255 { 1 } else { 0 };
    let l2 = if n >= 1 && n <= 63 { 1 } else { 0 };
    let hi = b.iter().any(|&c| c >= 0x80);
    let l3 = if hi { 0 } else { 1 };
    let l4 = if hi { 1 } else { 0 };
    format!("{}{}{}{}", l1, l2, l3, l4)
}

fn main() {
    // xorshift rng
    let mut s: u64 = 0x243F6A8885A308D3;
    let mut next = move || { s ^= s << 13; s ^= s >> 7; s ^= s << 17; s };
    let mut bad = 0usize;
    let mut tested = 0usize;

    // alphabet pools to bias toward interesting bytes
    let pools: Vec<Vec<u8>> = vec![
        b"a".to_vec(),
        b"a.-_".to_vec(),
        b"abcdefghij.-".to_vec(),
        (1u8..=127).collect(),
        (1u8..=255).collect(),
        vec![0xc3,0xa9,0xe4,0xbe,0x8b,0x80,0xff,0xf0,0x9f,0x98,0x80,b'a',b'.'],
        vec![0x80,0xbf,0xc0,0xc1,0xf5,0xff,0xfe,0xed,0xa0,0x80],
        b"xn--0123456789abcdef.".to_vec(),
    ];

    for _ in 0..40000 {
        let r = next();
        // lengths biased to boundaries
        let lens = [0usize,1,2,62,63,64,65,127,128,190,254,255,256,257,300,511,512,600,1000];
        let n = if r % 3 == 0 { lens[(next() as usize) % lens.len()] }
                else { (next() as usize) % 400 };
        let pool = &pools[(next() as usize) % pools.len()];
        let mut v = Vec::with_capacity(n);
        for _ in 0..n {
            let c = pool[(next() as usize) % pool.len()];
            v.push(if c == 0 { b'a' } else { c });
        }
        let got = run(&v);
        let exp = model(&v);
        tested += 1;
        if got != exp {
            bad += 1;
            println!("MISMATCH got={} exp={} len={} bytes={:02x?}", got, exp, v.len(),
                     &v[..v.len().min(80)]);
            if bad > 20 { break; }
        }
    }
    println!("tested={} mismatches={}", tested, bad);
}
EOF
